text:
Select an MLB team, pick a home run hit by a player on that team, and choose any stadium to see the true physical outline of the ballpark and test if the ball clears the fence.


all_hrs = transpose(hr_data)
all_parks = transpose(parks_data)

unique_teams = Array.from(new Set(all_hrs.map(d =&gt; d.team))).sort()

// 1. Pick a Team
viewof selected_team = Inputs.select(
  unique_teams,
  {
    label: html`&lt;strong&gt;1. Pick a Team:&lt;/strong&gt;`,
    value: "New York Yankees"
  }
)

// Filter home runs to the selected team
team_hrs = all_hrs.filter(d =&gt; d.team === selected_team)

// 2. Pick a Home Run from that team
viewof selected_hr = Inputs.select(
  team_hrs,
  {
    label: html`&lt;strong&gt;2. Pick a Home Run:&lt;/strong&gt;`,
    format: d =&gt; d.label
  }
)

// 3. Pick a Target Stadium
viewof selected_park = Inputs.select(
  all_parks,
  {
    label: html`&lt;strong&gt;3. Pick a Target Stadium:&lt;/strong&gt;`,
    value: all_parks.find(p =&gt; p.venue === "Fenway Park") || all_parks[0],
    format: d =&gt; `${d.venue} (${d.team})`
  }
)



















































wall_pts = selected_park && selected_park.wall_json ? JSON.parse(selected_park.wall_json) : []

// Calculate exact fence distance at the batted ball's spray angle using the true wall shape
interpolated_fence = {
  if (!selected_hr || !wall_pts.length) return 400;
  const theta = selected_hr.spray_angle;

  if (theta &lt;= wall_pts[0].angle) return wall_pts[0].dist;
  if (theta &gt;= wall_pts[wall_pts.length - 1].angle) return wall_pts[wall_pts.length - 1].dist;

  for (let i = 0; i &lt; wall_pts.length - 1; i++) {
    if (theta &gt;= wall_pts[i].angle && theta &lt;= wall_pts[i + 1].angle) {
      const span = wall_pts[i + 1].angle - wall_pts[i].angle;
      if (span === 0) return wall_pts[i].dist;
      const t = (theta - wall_pts[i].angle) / span;
      return wall_pts[i].dist + t * (wall_pts[i + 1].dist - wall_pts[i].dist);
    }
  }
  return 400;
}

margin = selected_hr ? Math.round(selected_hr.hit_distance_sc - interpolated_fence) : 0
is_homerun = margin &gt;= 0






























// Outcome Banner and Metrics Cards
html`
&lt;div style="margin-top: 1rem; margin-bottom: 1.5rem;"&gt;
  &lt;div style="
    padding: 1rem 1.25rem;
    border-radius: 8px;
    font-size: 1.15rem;
    font-weight: 600;
    color: ${is_homerun ? '#155724' : '#721c24'};
    background-color: ${is_homerun ? '#d4edda' : '#f8d7da'};
    border: 1px solid ${is_homerun ? '#c3e6cb' : '#f5c6cb'};
    margin-bottom: 1rem;
    display: flex;
    align-items: center;
    gap: 0.75rem;
  "&gt;
    &lt;span style="font-size: 1.6rem;"&gt;${is_homerun ? '⚾' : '❌'}&lt;/span&gt;
    &lt;div&gt;
      &lt;div&gt;${is_homerun ? 'HOME RUN!' : 'NOT A HOME RUN (OUT / OFF THE WALL)'}&lt;/div&gt;
      &lt;div style="font-size: 0.95rem; font-weight: normal; margin-top: 0.2rem;"&gt;
        ${is_homerun 
          ? `Cleared the fence at &lt;b&gt;${selected_park.venue}&lt;/b&gt; by &lt;b&gt;+${margin} ft&lt;/b&gt;.` 
          : `Fell short of the fence at &lt;b&gt;${selected_park.venue}&lt;/b&gt; by &lt;b&gt;${Math.abs(margin)} ft&lt;/b&gt;.`}
      &lt;/div&gt;
    &lt;/div&gt;
  &lt;/div&gt;

  &lt;div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 0.75rem;"&gt;
    &lt;div style="background: #f8f9fa; border: 1px solid #e9ecef; border-radius: 6px; padding: 0.75rem 1rem;"&gt;
      &lt;div style="color: #6c757d; font-size: 0.8rem; text-transform: uppercase;"&gt;Hit Distance&lt;/div&gt;
      &lt;div style="font-size: 1.3rem; font-weight: bold; color: #212529;"&gt;${selected_hr ? selected_hr.hit_distance_sc : '--'} ft&lt;/div&gt;
    &lt;/div&gt;
    &lt;div style="background: #f8f9fa; border: 1px solid #e9ecef; border-radius: 6px; padding: 0.75rem 1rem;"&gt;
      &lt;div style="color: #6c757d; font-size: 0.8rem; text-transform: uppercase;"&gt;Wall Distance at Angle&lt;/div&gt;
      &lt;div style="font-size: 1.3rem; font-weight: bold; color: #212529;"&gt;${Math.round(interpolated_fence)} ft&lt;/div&gt;
    &lt;/div&gt;
    &lt;div style="background: #f8f9fa; border: 1px solid #e9ecef; border-radius: 6px; padding: 0.75rem 1rem;"&gt;
      &lt;div style="color: #6c757d; font-size: 0.8rem; text-transform: uppercase;"&gt;Exit Velocity&lt;/div&gt;
      &lt;div style="font-size: 1.3rem; font-weight: bold; color: #212529;"&gt;${selected_hr ? selected_hr.launch_speed : '--'} mph&lt;/div&gt;
    &lt;/div&gt;
    &lt;div style="background: #f8f9fa; border: 1px solid #e9ecef; border-radius: 6px; padding: 0.75rem 1rem;"&gt;
      &lt;div style="color: #6c757d; font-size: 0.8rem; text-transform: uppercase;"&gt;Launch Angle&lt;/div&gt;
      &lt;div style="font-size: 1.3rem; font-weight: bold; color: #212529;"&gt;${selected_hr ? selected_hr.launch_angle : '--'}°&lt;/div&gt;
    &lt;/div&gt;
  &lt;/div&gt;
&lt;/div&gt;
`







// Dynamic SVG Ballpark Visualization showing actual stadium wall outline
viewof field_svg = {
  const width = 550;
  const height = 500;
  const cx = 275;
  const cy = 460;
  const scale = 0.9; // pixels per foot

  if (!selected_hr || !selected_park) return html`&lt;div&gt;Loading simulator...&lt;/div&gt;`;

  // Batted ball landing location in SVG coordinates
  const rad = selected_hr.spray_angle * (Math.PI / 180);
  const ball_x = cx + scale * (selected_hr.hit_distance_sc * Math.sin(rad));
  const ball_y = cy - scale * (selected_hr.hit_distance_sc * Math.cos(rad));

  // Infield bases (90 ft diamond scaled)
  const d90 = 90 * Math.SQRT1_2 * scale;
  const p1B = { x: cx + d90, y: cy - d90 };
  const p2B = { x: cx, y: cy - 90 * Math.SQRT2 * scale };
  const p3B = { x: cx - d90, y: cy - d90 };
  const pMound = { x: cx, y: cy - 60.5 * scale };

  return html`
  &lt;div style="display: flex; justify-content: center; margin-top: 1rem;"&gt;
    &lt;svg width="${width}" height="${height}" style="background: #1e3a1e; border-radius: 12px; box-shadow: 0 4px 14px rgba(0,0,0,0.25);"&gt;
      &lt;defs&gt;
        &lt;!-- Infield dirt gradient --&gt;
        &lt;radialGradient id="dirtGrad" cx="50%" cy="50%" r="50%"&gt;
          &lt;stop offset="0%" stop-color="#c68a4c" /&gt;
          &lt;stop offset="100%" stop-color="#9a5e27" /&gt;
        &lt;/radialGradient&gt;
      &lt;/defs&gt;

      &lt;!-- Actual Fair Territory for this Stadium --&gt;
      &lt;path d="${selected_park.field_svg_d}" fill="#2e6336" /&gt;

      &lt;!-- Left and Right Foul Lines to Poles --&gt;
      &lt;line x1="${cx}" y1="${cy}" x2="${selected_park.lf_x}" y2="${selected_park.lf_y}" 
            stroke="#ffffff" stroke-width="2" stroke-opacity="0.8" /&gt;
      &lt;line x1="${cx}" y1="${cy}" x2="${selected_park.rf_x}" y2="${selected_park.rf_y}" 
            stroke="#ffffff" stroke-width="2" stroke-opacity="0.8" /&gt;

      &lt;!-- Infield Dirt Diamond & Pitcher's Mound --&gt;
      &lt;path d="M ${cx} ${cy} L ${p3B.x} ${p3B.y} L ${p2B.x} ${p2B.y} L ${p1B.x} ${p1B.y} Z" fill="url(#dirtGrad)" opacity="0.9" /&gt;
      &lt;circle cx="${cx}" cy="${cy}" r="14" fill="url(#dirtGrad)" /&gt;
      &lt;circle cx="${pMound.x}" cy="${pMound.y}" r="10" fill="url(#dirtGrad)" /&gt;

      &lt;!-- Base Paths --&gt;
      &lt;line x1="${cx}" y1="${cy}" x2="${p1B.x}" y2="${p1B.y}" stroke="#ffffff" stroke-width="1.5" stroke-dasharray="3,3" /&gt;
      &lt;line x1="${p1B.x}" y1="${p1B.y}" x2="${p2B.x}" y2="${p2B.y}" stroke="#ffffff" stroke-width="1.5" stroke-dasharray="3,3" /&gt;
      &lt;line x1="${p2B.x}" y1="${p2B.y}" x2="${p3B.x}" y2="${p3B.y}" stroke="#ffffff" stroke-width="1.5" stroke-dasharray="3,3" /&gt;
      &lt;line x1="${p3B.x}" y1="${p3B.y}" x2="${cx}" y2="${cy}" stroke="#ffffff" stroke-width="1.5" stroke-dasharray="3,3" /&gt;

      &lt;!-- Bases --&gt;
      &lt;rect x="${p1B.x - 3}" y="${p1B.y - 3}" width="6" height="6" fill="#ffffff" transform="rotate(45 ${p1B.x} ${p1B.y})" /&gt;
      &lt;rect x="${p2B.x - 3}" y="${p2B.y - 3}" width="6" height="6" fill="#ffffff" transform="rotate(45 ${p2B.x} ${p2B.y})" /&gt;
      &lt;rect x="${p3B.x - 3}" y="${p3B.y - 3}" width="6" height="6" fill="#ffffff" transform="rotate(45 ${p3B.x} ${p3B.y})" /&gt;
      &lt;polygon points="${cx},${cy} ${cx-3},${cy-3} ${cx-3},${cy-6} ${cx+3},${cy-6} ${cx+3},${cy-3}" fill="#ffffff" /&gt;

      &lt;!-- True Physical Outfield Wall of this Specific Stadium --&gt;
      &lt;path d="${selected_park.wall_svg_d}" 
            fill="none" stroke="#f1c40f" stroke-width="4.5" stroke-linecap="round" stroke-linejoin="round" /&gt;

      &lt;!-- Foul Pole Markers --&gt;
      &lt;circle cx="${selected_park.lf_x}" cy="${selected_park.lf_y}" r="4" fill="#f1c40f" stroke="#000" stroke-width="1" /&gt;
      &lt;circle cx="${selected_park.rf_x}" cy="${selected_park.rf_y}" r="4" fill="#f1c40f" stroke="#000" stroke-width="1" /&gt;
      &lt;text x="${selected_park.lf_x - 6}" y="${selected_park.lf_y - 6}" fill="#f1c40f" font-size="11" font-weight="bold" text-anchor="end"&gt;${selected_park.left_line}′&lt;/text&gt;
      &lt;text x="${selected_park.rf_x + 6}" y="${selected_park.rf_y - 6}" fill="#f1c40f" font-size="11" font-weight="bold" text-anchor="start"&gt;${selected_park.right_line}′&lt;/text&gt;
      &lt;text x="${cx}" y="78" fill="#f1c40f" font-size="11" font-weight="bold" text-anchor="middle"&gt;CF ${selected_park.center}′&lt;/text&gt;

      &lt;!-- Ball Flight Path --&gt;
      &lt;line x1="${cx}" y1="${cy}" x2="${ball_x}" y2="${ball_y}" 
            stroke="${is_homerun ? '#2ecc71' : '#e74c3c'}" stroke-width="2.5" stroke-dasharray="5,4" /&gt;

      &lt;!-- Ball Landing Spot --&gt;
      &lt;circle cx="${ball_x}" cy="${ball_y}" r="7" 
              fill="${is_homerun ? '#2ecc71' : '#e74c3c'}" stroke="#ffffff" stroke-width="2" /&gt;
      &lt;circle cx="${ball_x}" cy="${ball_y}" r="12" 
              fill="none" stroke="${is_homerun ? '#2ecc71' : '#e74c3c'}" stroke-width="1.5" opacity="0.6" /&gt;

      &lt;!-- Ball Landing Label --&gt;
      &lt;text x="${ball_x}" y="${ball_y - 14}" fill="#ffffff" font-size="12" font-weight="bold" text-anchor="middle"
            filter="drop-shadow(0px 1px 3px rgba(0,0,0,0.9))"&gt;
        ${selected_hr.hit_distance_sc} ft
      &lt;/text&gt;

      &lt;!-- Ballpark Title & Metadata Badge --&gt;
      &lt;rect x="12" y="12" width="220" height="48" rx="6" fill="rgba(0,0,0,0.5)" /&gt;
      &lt;text x="20" y="32" fill="#ffffff" font-size="13" font-weight="bold"&gt;${selected_park.venue}&lt;/text&gt;
      &lt;text x="20" y="48" fill="#d0d0d0" font-size="11"&gt;${selected_park.team} • ${selected_park.city}, ${selected_park.state}&lt;/text&gt;
    &lt;/svg&gt;
  &lt;/div&gt;
  `;
}
